from . import db
from openlibrary.core.bookshelves import Bookshelves


class Bestbook(db.CommonExtras):
    """Best Book Award nominations."""

    TABLENAME = "bestbook"
    PRIMARY_KEY = "id"

    class AwardConditionsError(Exception):
        pass

    @classmethod
    def add(
        cls,
        username: str,
        work_id: str,
        topic: str,
        comment: str = '',
        edition_id: int | None = None,
    ) -> int | None:
        """Adds an award when conditions are met, otherwise raises AwardConditionsError."""
        if not Bookshelves.user_has_read_work(username, work_id):
            raise cls.AwardConditionsError(
                'Only books which have been marked as read may be given awards'
            )
        if cls.get_awards(work_id=work_id, username=username):
            raise cls.AwardConditionsError(
                'You have already given an award to this work'
            )
        if cls.get_awards(topic=topic, username=username):
            raise cls.AwardConditionsError(
                'You have already used this topic for another work'
            )

        oldb = db.get_db()
        return oldb.insert(
            cls.TABLENAME,
            username=username,
            work_id=work_id,
            topic=topic,
            comment=comment,
            edition_id=edition_id,
        )

    @classmethod
    def remove(
        cls, username: str, work_id: str | None = None, topic: str | None = None
    ) -> int:
        """Removes any award for the username where the work_id or topic matches."""
        conditions = []
        vars: dict = {'username': username}
        if work_id is not None:
            conditions.append("work_id=$work_id")
            vars['work_id'] = work_id
        if topic is not None:
            conditions.append("topic=$topic")
            vars['topic'] = topic
        if not conditions:
            return 0
        where = "username=$username AND (" + " OR ".join(conditions) + ")"
        oldb = db.get_db()
        return oldb.delete(cls.TABLENAME, where=where, vars=vars)

    @classmethod
    def prepare_query(
        cls,
        select: str = '*',
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> tuple[str, dict]:
        """Builds the SQL query and bound variables for matching awards."""
        query = f"SELECT {select} FROM {cls.TABLENAME}"
        conditions = []
        vars: dict = {}
        if work_id is not None:
            conditions.append("work_id=$work_id")
            vars['work_id'] = work_id
        if username is not None:
            conditions.append("username=$username")
            vars['username'] = username
        if topic is not None:
            conditions.append("topic=$topic")
            vars['topic'] = topic
        if conditions:
            query += " WHERE " + " AND ".join(conditions)
        return query, vars

    @classmethod
    def get_count(
        cls,
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> int:
        query, vars = cls.prepare_query(
            select='count(*) AS count', work_id=work_id, username=username, topic=topic
        )
        oldb = db.get_db()
        result = list(oldb.query(query, vars=vars))
        return result[0].count if result else 0

    @classmethod
    def get_awards(
        cls,
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> list:
        query, vars = cls.prepare_query(
            work_id=work_id, username=username, topic=topic
        )
        oldb = db.get_db()
        return list(oldb.query(query, vars=vars))

    @classmethod
    def get_leaderboard(cls) -> list[dict]:
        oldb = db.get_db()
        query = (
            f"SELECT work_id, count(*) AS count FROM {cls.TABLENAME} "
            "GROUP BY work_id ORDER BY count DESC"
        )
        return list(oldb.query(query))
