    path = r"/works/OL(\d+)W/awards"
    encoding = "json"

    def POST(self, work_id):
        """
        Add, update, or remove a Best Book Award nomination for a work.

        :param str work_id: e.g. 123 (from /works/OL123W)
        """
        i = web.input(
            op="add",
            topic="",
            comment="",
            edition_key=None,
        )

        user = accounts.get_current_user()
        if not user:
            return delegate.RawText(
                json.dumps({'errors': 'Authentication failed'}),
                content_type="application/json",
            )

        username = user.key.split('/')[-1]
        edition_key = i.get('edition_key')
        edition_id = (
            int(extract_numeric_id_from_olid(edition_key)) if edition_key else None
        )

        if i.op in ["add", "update"]:
            try:
                award = Bestbook.add(
                    username=username,
                    work_id=work_id,
                    topic=i.topic,
                    comment=i.comment or "",
                    edition_id=edition_id,
                )
            except Bestbook.AwardConditionsError as error:
                return delegate.RawText(
                    json.dumps({'errors': str(error)}),
                    content_type="application/json",
                )
            return delegate.RawText(
                json.dumps({'success': True, 'award': award}),
                content_type="application/json",
