+
+import React, { ReactElement, useEffect, useState } from "react";
+import { Room } from "matrix-js-sdk/src/models/room";
+import { RoomMember } from "matrix-js-sdk/src/models/room-member";
+import { MatrixEvent } from "matrix-js-sdk/src/models/event";
+import { logger } from "matrix-js-sdk/src/logger";
+
+import dis from "../dispatcher/dispatcher";
+import { MatrixClientPeg } from "../MatrixClientPeg";
+import { getPrimaryPermalinkEntity } from "../utils/permalinks/Permalinks";
+import { Action } from "../dispatcher/actions";
+import RoomAvatar from "../components/views/avatars/RoomAvatar";
+import MemberAvatar from "../components/views/avatars/MemberAvatar";
+import { ButtonEvent } from "../components/views/elements/AccessibleButton";
+import { PillType } from "../components/views/elements/Pill";
+
+export interface PermalinkArgs {
+    room?: Room;
+    type?: PillType;
+    url?: string;
+}
+
+export interface HookResult {
+    avatar: ReactElement | null;
+    text: string | null;
+    onClick: ((e: ButtonEvent) => void) | null;
+    resourceId: string | null;
+    type: PillType | "space" | null;
+}
+
+interface ProfileInfo {
+    userId: string;
+    displayname?: string;
+    avatarUrl?: string;
+}
+
+const EMPTY_RESULT: HookResult = {
+    avatar: null,
+    text: null,
+    onClick: null,
+    resourceId: null,
+    type: null,
+};
+
+// Evaluated lazily (not at module load) because of the circular import with Pill.tsx
+const typeForPrefix = (prefix: string | undefined): PillType | undefined => {
+    switch (prefix) {
+        case "@":
+            return PillType.UserMention;
+        case "#":
+        case "!":
+            return PillType.RoomMention;
+        default:
+            return undefined;
+    }
+};
+
+const buildMember = (userId: string, profile: ProfileInfo | null): RoomMember => {
+    const member = new RoomMember(null, userId);
+    if (profile) {
+        member.name = profile.displayname;
+        member.rawDisplayName = profile.displayname;
+        member.events.member = {
+            getContent: () => {
+                return { avatar_url: profile.avatarUrl };
+            },
+            getDirectionalContent: function () {
+                return this.getContent();
+            },
+        } as MatrixEvent;
+    }
+    return member;
+};
+
+export const usePermalink = ({ url, type: propsType, room }: PermalinkArgs): HookResult => {
+    const [profile, setProfile] = useState<ProfileInfo | null>(null);
+
+    let resourceId: string | null = null;
+    if (url) {
+        resourceId = getPrimaryPermalinkEntity(url) || null;
+    }
+    const prefix = resourceId ? resourceId[0] : undefined;
+    const type = propsType || typeForPrefix(prefix);
+    const isUser = type === PillType.UserMention;
+    const localMember = isUser && resourceId ? room?.getMember(resourceId) ?? undefined : undefined;
+    const needsProfileLookup = isUser && !!resourceId && !localMember;
+
+    useEffect(() => {
+        if (!needsProfileLookup || !resourceId) return;
+        const userId = resourceId;
+        let cancelled = false;
+        MatrixClientPeg.get()
+            .getProfileInfo(userId)
+            .then((resp) => {
+                if (cancelled) return;
+                setProfile({ userId, displayname: resp.displayname, avatarUrl: resp.avatar_url });
+            })
+            .catch((err) => {
+                logger.error("Could not retrieve profile data for " + userId + ":", err);
+            });
+        return () => {
+            cancelled = true;
+        };
+    }, [needsProfileLookup, resourceId]);
+
+    if (!type) {
+        return EMPTY_RESULT;
+    }
+
+    switch (type) {
+        case PillType.AtRoomMention:
+            return {
+                avatar: room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
+                text: "@room",
+                onClick: null,
+                resourceId: null,
+                type: PillType.AtRoomMention,
+            };
+        case PillType.UserMention: {
+            if (!resourceId) return EMPTY_RESULT;
+            const member: RoomMember =
+                localMember ?? buildMember(resourceId, profile && profile.userId === resourceId ? profile : null);
+            const onClick = (e: ButtonEvent): void => {
+                e.preventDefault();
+                dis.dispatch({
+                    action: Action.ViewUser,
+                    member,
+                });
+            };
+            return {
+                avatar: <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />,
+                text: member.rawDisplayName || resourceId,
+                onClick,
+                resourceId,
+                type: PillType.UserMention,
+            };
+        }
+        case PillType.RoomMention: {
+            if (!resourceId) return EMPTY_RESULT;
+            const client = MatrixClientPeg.get();
+            const localRoom =
+                resourceId[0] === "#"
+                    ? client
+                          .getRooms()
+                          .find((r) => r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId))
+                    : client.getRoom(resourceId);
+            return {
+                avatar: localRoom ? <RoomAvatar room={localRoom} width={16} height={16} aria-hidden="true" /> : null,
+                text: localRoom?.name || resourceId,
+                onClick: null,
+                resourceId,
+                type: localRoom?.isSpaceRoom() ? "space" : PillType.RoomMention,
+            };
+        }
+        default:
+            return EMPTY_RESULT;
+    }
+};
